item.aggregated_output:
                _mapping(item, "review answer")
                for item in _list(value["answers"], "answers")
            )
        )
        return ReviewDecision(
            schema_version=value["schema_version"],
            protocol_id=value["protocol_id"],
            review_decision_sha256=value["review_decision_sha256"],
            review_packet_sha256=value["review_packet_sha256"],
            candidate_id=value["candidate_id"],
            reviewer_role=ReviewerRole(value["reviewer_role"]),
            human_action=HumanReviewAction(value["human_action"]),
            changed_question_ids=tuple(
                _list(value["changed_question_ids"], "changed_question_ids")
            ),
            focal_hypothesis=_focal_hypothesis(value["focal_hypothesis"]),
            answers=answers,
            outcome=ReviewOutcome(value["outcome"]),
            non_authoritative_commentary=value["non_authoritative_commentary"],
        )
    except (KeyError, TypeError, ValueError) as error:
        if isinstance(error, ResultValidationError):
            raise
        raise ResultValidationError("review decision value is invalid") from error


def validate_review_decision_bytes(
    encoded: bytes,
    packet: ReviewPacket,
) -> ReviewDecision:
    try:
        value = json.loads(encoded.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ResultValidationError("review decision is not UTF-8 JSON") from error
    if not isinstance(value, dict) or canonical_json_bytes(value) != encoded:
        raise ResultValidationError("review decision is not canonical JSON")
    decision = review_decision_from_mapping(value)
    try:
        if review_decision_bytes(decision) != encoded:
            raise ResultValidationError("review decision bytes are not reproducible")
    except ValueError as error:
        raise ResultValidationError("review decision hash is invalid") from error
    if (
        packet.review_packet_sha256 is None
        or decision.review_packet_sha256 != packet.review_packet_sha256
        or decision.candidate_id != packet.candidate_result.candidate_id
    ):
        raise ResultValidationError("review decision and packet identities differ")
    resolvable = {item.evidence_id for item in packet.evidence_index}
    cited = set(decision.focal_hypothesis.evidence_refs)
    cited.update(ref for answer in decision.answers for ref in answer.evidence_refs)
    if not cited <= resolvable:
        raise ResultValidationError("review decision contains unresolved evidence refs")
    return decision


def second_review_hash_bucket(candidate_id: str) -> int:
    if not candidate_id:
        raise ValueError("candidate_id must be non-empty")
    digest = hashlib.sha256((HYBRID_PROTOCOL_ID + candidate_id).encode("utf-8"))
    return int.from_bytes(digest.digest(), byteorder="big") % 100


def second_review_requirement(
    decision: ReviewDecision,
    result: CandidateResult,
) -> SecondReviewRequirement:
    if decision.candidate_id != result.candidate_id:
        raise ValueError("review decision and TPTM result candidate IDs differ")
    bucket = second_review_hash_bucket(result.candidate_id)
    if decision.outcome is ReviewOutcome.REVIEW_RETAIN:
        return SecondReviewRequirement(True, SecondReviewReason.EVERY_RETAIN, bucket)
    if decision.outcome is ReviewOutcome.REVIEW_UNRESOLVED:
        return SecondReviewRequirement(
            True,
            SecondReviewReason.UNRESOLVED_MAY_BECOME_RETAIN,
            bucket,
        )
    has_positive_tptm_evidence = bool(
        result.trust_transitions
        or result.witness_candidates
        or result.triplet_envelope_status
        in {
            TripletEnvelopeStatus.TRIPLET_ENVELOPE_FEASIBLE,
            TripletEnvelopeStatus.TRIPLET_ENVELOPE_AMBIGUOUS,
        }
    )
    if has_positive_tptm_evidence:
        return SecondReviewRequirement(
            True,
            SecondReviewReason.REJECT_WITH_POSITIVE_TPTM_EVIDENCE,
            bucket,
        )
    if bucket < 20:
        return SecondReviewRequirement(
            True,
            SecondReviewReason.HASH_SELECTED_REJECT_SAMPLE,
            bucket,
        )
    return SecondReviewRequirement(False, SecondReviewReason.NOT_SELECTED, bucket)


def adjudicate_reviews(
    first: ReviewDecision,
    second: ReviewDecision,
) -> ReviewAdjudication:
    if (
        first.candidate_id != second.candidate_id
        or first.review_packet_sha256 != second.review_packet_sha256
    ):
        raise ValueError("review decisions do not concern the same packet")
    if (
        first.outcome is not second.outcome
        or first.focal_hypothesis != second.focal_hypothesis
    ):
        return ReviewAdjudication(
            ReviewOutcome.REVIEW_UNRESOLVED,
            ReviewAdjudicationAction.CONSTRAINED_FAMILY_FEASIBILITY_INVESTIGATION,
        )
    return ReviewAdjudication(first.outcome, ReviewAdjudicationAction.AGREEMENT)
